function prefixEchoes(text, lengths) {
  return lengths.map((length) => {
    let count = 0;
    for (let start = 0; start + length <= text.length; start++) {
      let offset = 0;
      while (offset < length && text[start + offset] === text[offset]) offset++;
      if (offset === length) count++;
    }
    return count;
  });
}

function prefixEchoes(text, lengths) {
  const n = text.length;
  const z = new Int32Array(n);
  z[0] = n;
  for (let i = 1, left = 0, right = 0; i < n; i++) {
    if (i < right) z[i] = Math.min(right - i, z[i - left]);
    while (i + z[i] < n && text[z[i]] === text[i + z[i]]) z[i]++;
    if (i + z[i] > right) {
      left = i;
      right = i + z[i];
    }
  }
  const atLeast = new Int32Array(n + 2);
  for (let i = 0; i < n; i++) atLeast[z[i]]++;
  for (let length = n - 1; length >= 1; length--) atLeast[length] += atLeast[length + 1];
  return lengths.map((length) => atLeast[length]);
}

function prefixEchoes(text, lengths) {
  const n = text.length;
  const border = new Int32Array(n);
  for (let i = 1, k = 0; i < n; i++) {
    while (k > 0 && text[i] !== text[k]) k = border[k - 1];
    if (text[i] === text[k]) k++;
    border[i] = k;
  }
  const echoes = new Int32Array(n + 1).fill(1);
  for (let length = n; length >= 1; length--) {
    if (border[length - 1] > 0) echoes[border[length - 1]] += echoes[length];
  }
  return lengths.map((length) => echoes[length]);
}
